//! The Assets workspace's state: the files the project adds to the archives,
//! and a picture turned into a BLP texture.
//!
//! ## What an asset is here
//!
//! Every file of the project that the publish packs: the client's files, and
//! none of the project's bookkeeping or server files
//! ([`Project::NOT_GAME_DATA`]). Some are imported: a texture, a model with its
//! textures ([`super::models`]), a WAV or MP3 sound ([`super::sounds`]). Some
//! are generated by the editor: a model baked in the attachment lab, a minimap
//! picture, a baked NPC skin, a flight map ([`super::generated`]). The import
//! record ([`super::sources`]) tells those two apart. The rest are edited in
//! the editor's other workspaces: client tables, map tiles and tile indexes.
//!
//! Every one is a file in the project folder at its archive path. A read
//! through the overlay finds it at once, and [`EditSession::listed`] adds it
//! to every picker built from the archives' listing; nothing else registers
//! it. The publish packs it with the rest of the project.
//!
//! Import takes one picture, one model file, or one or more WAV or MP3 files,
//! and opens the Import Texture, Import Model or Import Sound dialog by the
//! files' extensions.
//!
//! ## Importing a texture
//!
//! A PNG, TGA or BLP picture is read to RGBA pixels and written as a BLP with
//! [`vale_assets::world::blp::encode`], in one of the three DXT shapes the
//! shipped archives use and with its mip chain. Both sides must be powers of
//! two, as every shipped texture's are; a picture whose sides are not is
//! resized up to the next powers of two when the dialog asks for it. The file
//! is saved through [`EditSession::save_bytes`], so it is undone by removing
//! it, not by `Ctrl+Z`.
//!
//! ## The dialog asks what a texture is for, not where it goes
//!
//! A [`Purpose`] decides the folder, the size, the compression and the files
//! written, so a person chooses Ground texture rather than typing `Tileset\`.
//! The folder is shown and, for Other, typed; for a ground texture only the
//! folder under `Tileset\` is typed.
//!
//! A ground texture is two files, as the game ships its ground: `<name>.blp`
//! in DXT1 with no alpha, and `<name>_s.blp` in DXT3, the same picture with
//! the gloss mask in its alpha. The 1.12 client opens the `_s` file in place
//! of the plain one whenever its `specular` setting is on, and has no fallback
//! to the plain file, so a ground texture without one is drawn as a missing
//! texture. Every shipped tileset has both, and none is larger than 256x256;
//! every shipped icon is 64x64. The dialog scales a larger picture down to its
//! purpose's size unless asked not to.
//!
//! An import can be asked for by a form field (a creature display's skin):
//! the dialog then starts in that field's folder, and the field is set to the
//! imported texture's name once it is written. See [`FieldTarget`]. The
//! texture tool's panel asks for a ground texture, and the brush takes it once
//! it is written ([`Assets::imported`]).
//!
//! The file dialog is the system's own and blocks while it is open, so it is
//! run by [`answer`], outside the panel, as the tile tool runs its picture
//! dialogs.

use crate::session::EditSession;
use vale_assets::world::blp::{self, Encoding};
use vale_edit::manifest::Kind;
use vale_edit::project::Project;
use bevy::prelude::*;
use std::path::{Path, PathBuf};

/// Where a ground texture goes, and the folder under it the dialog starts in.
pub(crate) const GROUND_ROOT: &str = "Tileset\\";
pub(crate) const GROUND_FOLDER: &str = "Tileset\\Custom\\";
/// Where an icon goes.
pub(crate) const ICON_FOLDER: &str = "Interface\\Icons\\";
/// Where any other texture starts.
pub(crate) const OTHER_FOLDER: &str = "Textures\\Custom\\";

/// What an imported texture is for. It decides where the texture is written,
/// how large it is and which files are written. See the module comment.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum Purpose {
    /// Ground, painted with the texture tool: under `Tileset\`, as a pair with
    /// its `_s` gloss file, at most 256x256.
    Ground,
    /// A bag, spell or button icon: in `Interface\Icons\`, 64x64.
    Icon,
    /// The texture a form field names, in the folder the field's file is found
    /// in. Only a field asks for this; see [`FieldTarget`].
    Field,
    /// Any other texture, in a folder typed in the dialog.
    Other,
}

impl Purpose {
    /// The purposes the dialog offers a choice between. A field's import is
    /// its field's.
    pub(crate) const OFFERED: [Purpose; 3] = [Purpose::Ground, Purpose::Icon, Purpose::Other];

    pub(crate) fn name(self) -> &'static str {
        match self {
            Purpose::Ground => "Ground texture",
            Purpose::Icon => "Icon",
            Purpose::Field => "For the field",
            Purpose::Other => "Other",
        }
    }

    /// One line on what it is for and what is written.
    pub(crate) fn hint(self) -> &'static str {
        match self {
            Purpose::Ground => "Painted on the terrain with the texture tool. Written as the \
                                texture and its _s gloss file, as the game's ground is.",
            Purpose::Icon => "An item, spell or button icon in Interface\\Icons\\, 64x64 as \
                              every shipped icon is.",
            Purpose::Field => "Named by the field that asked, in the folder it is read from.",
            Purpose::Other => "Any other texture, in the folder below: a model's skin, a \
                               loading screen, a particle.",
        }
    }

    /// The side the purpose's shipped textures are at most, which an import
    /// is scaled down to unless the dialog says otherwise.
    pub(crate) fn largest(self) -> Option<u32> {
        match self {
            Purpose::Ground => Some(GROUND_SIDE),
            Purpose::Icon => Some(ICON_SIDE),
            Purpose::Field | Purpose::Other => None,
        }
    }

    /// What a texture at `vpath` is for, from its folder.
    pub(crate) fn of_path(vpath: &str) -> Purpose {
        let lower = vpath.replace('/', "\\").to_ascii_lowercase();
        if lower.starts_with("tileset\\") {
            Purpose::Ground
        } else if lower.starts_with("interface\\icons\\") {
            Purpose::Icon
        } else {
            Purpose::Other
        }
    }
}

/// The table field whose picker opened an import. A texture field is set to
/// the written texture's name; a sound field is set to the id of the
/// `SoundEntries` row the import adds ([`super::sounds`]).
#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) struct FieldTarget {
    pub(crate) table: String,
    pub(crate) record: usize,
    pub(crate) field: usize,
    /// The end of the file name the field leaves off, or nothing. A body
    /// texture's field names `Cloth_A_01Black_Sleeve_AU` and the file is
    /// `Cloth_A_01Black_Sleeve_AU_U.blp`, the `_U` for either body.
    pub(crate) suffix: &'static str,
}

impl FieldTarget {
    /// The file name an import for this field is written under: `name` with
    /// [`Self::suffix`], unless it already ends in one of the three a body
    /// texture can.
    pub(crate) fn file_name(&self, name: &str) -> String {
        let lower = name.to_ascii_lowercase();
        let suffixed = ["_u", "_m", "_f"].iter().any(|end| lower.ends_with(end));
        match self.suffix.is_empty() || suffixed {
            true => name.to_string(),
            false => format!("{name}{}", self.suffix),
        }
    }

    /// What the field is set to for a texture written as `file`: the name
    /// without its suffix, for a field that leaves one off.
    pub(crate) fn field_text(&self, file: &str) -> String {
        if self.suffix.is_empty() {
            return file.to_string();
        }
        let cut = file.len().saturating_sub(2);
        let lower = file.to_ascii_lowercase();
        match ["_u", "_m", "_f"].iter().any(|end| lower.ends_with(end)) {
            true => file[..cut].to_string(),
            false => file.to_string(),
        }
    }
}

/// The largest side of any ground texture the archives ship.
pub(crate) const GROUND_SIDE: u32 = 256;
/// The side of every icon the archives ship.
pub(crate) const ICON_SIDE: u32 = 64;

/// What a ground texture's `_s` file carries in its alpha, which the client
/// reads as the gloss mask: where the sun's highlight lies on the ground.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum Gloss {
    /// No highlight: the ground is drawn matte.
    Matte,
    /// The picture's own alpha.
    FromAlpha,
}

/// How the dialog chooses the compression.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum Choice {
    /// [`Encoding::for_pixels`]: the least that keeps the picture's alpha.
    Auto,
    Fixed(Encoding),
}

/// The open Import Texture dialog.
#[derive(Debug, Clone)]
pub(crate) struct Import {
    /// The picture on disk.
    pub(crate) source: PathBuf,
    pub(crate) width: u32,
    pub(crate) height: u32,
    pub(crate) rgba: Vec<u8>,
    /// What it is for. See [`Purpose`].
    pub(crate) purpose: Purpose,
    /// The archive folder it is written into, ending in a backslash. Under
    /// `Tileset\` for a ground texture and `Interface\Icons\` for an icon;
    /// [`Self::set_purpose`] keeps it so.
    pub(crate) folder: String,
    /// The file name, without `.blp`.
    pub(crate) name: String,
    pub(crate) choice: Choice,
    pub(crate) mips: bool,
    /// Resize to the next powers of two when a side is not one.
    pub(crate) resize: bool,
    /// For a ground texture, what its `_s` file's alpha is.
    pub(crate) gloss: Gloss,
    /// Scale it down to its purpose's largest side ([`Purpose::largest`]).
    pub(crate) shrink: bool,
    pub(crate) for_field: Option<FieldTarget>,
}

impl Import {
    /// The dialog's starting choices for a picture: the compression chosen
    /// from its alpha, mipmaps, a resize where a side is not a power of two,
    /// and for a ground texture, the gloss from its alpha where it has one and
    /// the scale-down.
    pub(crate) fn new(
        source: PathBuf,
        (width, height, rgba): (u32, u32, Vec<u8>),
        folder: String,
        name: String,
        for_field: Option<FieldTarget>,
    ) -> Import {
        let alpha = rgba.chunks_exact(4).any(|pixel| pixel[3] != 255);
        let purpose = match for_field {
            Some(_) => Purpose::Field,
            None => Purpose::of_path(&folder),
        };
        Import {
            purpose,
            source,
            width,
            height,
            resize: !width.is_power_of_two() || !height.is_power_of_two(),
            rgba,
            folder,
            name,
            choice: Choice::Auto,
            mips: true,
            gloss: match alpha {
                true => Gloss::FromAlpha,
                false => Gloss::Matte,
            },
            shrink: true,
            for_field,
        }
    }

    /// Whether it is a ground texture. See the module comment.
    pub(crate) fn ground(&self) -> bool {
        self.purpose == Purpose::Ground
    }

    /// Change what it is for, and the folder with it: a ground texture keeps
    /// a folder under `Tileset\` it already has, an icon goes to
    /// `Interface\Icons\`, and Other leaves either of those for its own
    /// folder.
    pub(crate) fn set_purpose(&mut self, purpose: Purpose) {
        let now = Purpose::of_path(&folder_of(&self.folder));
        self.folder = match purpose {
            Purpose::Ground if now == Purpose::Ground => folder_of(&self.folder),
            Purpose::Ground => GROUND_FOLDER.to_string(),
            Purpose::Icon => ICON_FOLDER.to_string(),
            Purpose::Other if now != Purpose::Other => OTHER_FOLDER.to_string(),
            Purpose::Other | Purpose::Field => folder_of(&self.folder),
        };
        self.purpose = purpose;
    }

    /// The size the texture is written at.
    pub(crate) fn written_size(&self) -> (u32, u32) {
        let (width, height) = match self.resize {
            true => (self.width.next_power_of_two(), self.height.next_power_of_two()),
            false => (self.width, self.height),
        };
        match (self.shrink, self.purpose.largest()) {
            (true, Some(side)) => (width.min(side), height.min(side)),
            _ => (width, height),
        }
    }

    /// The compression the texture is written with. A ground texture's plain
    /// file is DXT1, as every shipped one is; its `_s` file is DXT3.
    pub(crate) fn encoding(&self) -> Encoding {
        if self.ground() {
            return Encoding::Dxt1;
        }
        match self.choice {
            Choice::Auto => Encoding::for_pixels(&self.rgba),
            Choice::Fixed(encoding) => encoding,
        }
    }

    /// The archive path of a ground texture's `_s` file, or `None` for any
    /// other texture.
    pub(crate) fn gloss_vpath(&self) -> Option<String> {
        self.ground()
            .then(|| format!("{}{}_s.blp", folder_of(&self.folder), self.name.trim()))
    }

    /// The archive path it is written at.
    pub(crate) fn vpath(&self) -> String {
        format!("{}{}.blp", folder_of(&self.folder), self.name.trim())
    }

    /// Why it cannot be written as it stands, or nothing.
    pub(crate) fn problems(&self) -> Vec<String> {
        let name = self.name.trim();
        let mut out = name_problems(name);
        if folder_of(&self.folder).is_empty() {
            out.push("The folder is empty. No shipped texture is at the archive root; choose a folder.".to_string());
        }
        if !Project::is_game_data(&self.vpath()) {
            out.push("The folder is one of the project's own (sql, server, publish, editor), which is not published.".to_string());
        }
        let (width, height) = self.written_size();
        if !width.is_power_of_two() || !height.is_power_of_two() {
            out.push(format!(
                "{}x{} is not a power of two on each side. Resize, or import a picture that is.",
                self.width, self.height
            ));
        }
        if width > blp::MAX_SIDE || height > blp::MAX_SIDE {
            out.push(format!("{width}x{height} is larger than {0}x{0}.", blp::MAX_SIDE));
        }
        if self.ground() && !folder_of(&self.folder).to_ascii_lowercase().starts_with("tileset\\") {
            out.push("A ground texture's folder must be under Tileset\\.".to_string());
        }
        if self.ground() && name.to_ascii_lowercase().ends_with("_s") {
            out.push(
                "A ground texture's name may not end in _s: the client opens <name>_s.blp in \
                 its place, and would look for this one's as <name>_s_s.blp."
                    .to_string(),
            );
        }
        out
    }

    /// The files written, each archive path with its bytes: the texture, and
    /// for a ground texture its `_s` file beside it.
    pub(crate) fn encode(&self) -> Result<Vec<(String, Vec<u8>)>, String> {
        let (width, height) = self.written_size();
        let pixels = match (width, height) == (self.width, self.height) {
            true => self.rgba.clone(),
            false => blp::resize(&self.rgba, self.width, self.height, width, height),
        };
        let encode = |pixels: &[u8], encoding: Encoding| {
            blp::encode(pixels, width, height, encoding, self.mips).map_err(|e| e.to_string())
        };
        let Some(gloss_vpath) = self.gloss_vpath() else {
            return Ok(vec![(self.vpath(), encode(&pixels, self.encoding())?)]);
        };
        let opaque: Vec<u8> = pixels
            .chunks_exact(4)
            .flat_map(|pixel| [pixel[0], pixel[1], pixel[2], 255])
            .collect();
        let glossed: Vec<u8> = pixels
            .chunks_exact(4)
            .flat_map(|pixel| {
                let mask = match self.gloss {
                    Gloss::Matte => 0,
                    Gloss::FromAlpha => pixel[3],
                };
                [pixel[0], pixel[1], pixel[2], mask]
            })
            .collect();
        Ok(vec![
            (self.vpath(), encode(&opaque, Encoding::Dxt1)?),
            (gloss_vpath, encode(&glossed, Encoding::Dxt3)?),
        ])
    }
}

/// The `_s` gloss file beside a ground texture at `vpath`, or `None` for a
/// path that is not a ground texture's plain file.
pub(crate) fn gloss_of(vpath: &str) -> Option<String> {
    let lower = vpath.to_ascii_lowercase();
    let plain = Purpose::of_path(vpath) == Purpose::Ground
        && lower.ends_with(".blp")
        && !lower.ends_with("_s.blp");
    plain.then(|| format!("{}_s.blp", &vpath[..vpath.len() - 4]))
}

/// The characters a file name may not hold.
const NOT_IN_NAMES: [char; 9] = ['\\', '/', ':', '*', '?', '"', '<', '>', '|'];

/// The reasons `name` cannot be a file name; empty when it can.
pub(crate) fn name_problems(name: &str) -> Vec<String> {
    let mut out = Vec::new();
    if name.is_empty() {
        out.push("The name is empty.".to_string());
    }
    if name.contains(NOT_IN_NAMES) {
        out.push("The name may not contain \\ / : * ? \" < > |.".to_string());
    }
    out
}

/// `text` as a file name: the characters in `NOT_IN_NAMES` removed, the
/// ends trimmed and spaces replaced by underscores; `fallback` when nothing
/// is left.
pub(crate) fn clean_name(text: &str, fallback: &str) -> String {
    let cleaned: String = text
        .chars()
        .filter(|c| !NOT_IN_NAMES.contains(c))
        .collect::<String>()
        .trim()
        .replace(' ', "_");
    match cleaned.is_empty() {
        true => fallback.to_string(),
        false => cleaned,
    }
}

/// The folder part of a typed folder: backslashes, no leading separator, one
/// trailing backslash; empty for nothing typed.
pub(crate) fn folder_of(typed: &str) -> String {
    let cleaned = typed.trim().replace('/', "\\");
    let cleaned = cleaned.trim_matches('\\');
    match cleaned.is_empty() {
        true => String::new(),
        false => format!("{cleaned}\\"),
    }
}

/// A picture on disk as RGBA pixels, top row first: a PNG of any colour type
/// at 8 or 16 bits, a TGA, or a BLP's top level.
pub(crate) fn read_picture(path: &Path) -> Result<(u32, u32, Vec<u8>), String> {
    let said = |e: &dyn std::fmt::Display| format!("{}: {e}", path.display());
    let extension = path
        .extension()
        .and_then(|e| e.to_str())
        .unwrap_or("")
        .to_ascii_lowercase();
    let bytes = std::fs::read(path).map_err(|e| said(&e))?;
    read_picture_bytes(&bytes, &extension).map_err(|e| said(&e))
}

/// [`read_picture`] for bytes already read, the format named by an extension
/// (`png`) or a MIME type (`image/png`).
pub(crate) fn read_picture_bytes(bytes: &[u8], format: &str) -> Result<(u32, u32, Vec<u8>), String> {
    let format = format.to_ascii_lowercase();
    match format.trim_start_matches("image/") {
        "png" => read_png(bytes),
        "tga" | "x-tga" => {
            let tga = vale_assets::world::tga::decode(bytes).map_err(|e| e.to_string())?;
            Ok((tga.width, tga.height, tga.rgba))
        }
        "blp" => {
            let picture = blp::decode(bytes).map_err(|e| e.to_string())?;
            Ok((picture.width, picture.height, picture.rgba))
        }
        "jpeg" | "jpg" => Err("a JPEG picture is not read; save it as PNG".to_string()),
        other => Err(format!("a .{other} file is not a picture this reads; use PNG, TGA or BLP")),
    }
}

/// A PNG as RGBA8, whatever its colour type and depth.
fn read_png(bytes: &[u8]) -> Result<(u32, u32, Vec<u8>), String> {
    let mut decoder = png::Decoder::new(std::io::Cursor::new(bytes));
    decoder.set_transformations(png::Transformations::EXPAND | png::Transformations::STRIP_16);
    let mut reader = decoder.read_info().map_err(|e| e.to_string())?;
    let size = reader.output_buffer_size().ok_or("too large to read")?;
    let mut buffer = vec![0u8; size];
    let frame = reader.next_frame(&mut buffer).map_err(|e| e.to_string())?;
    buffer.truncate(frame.buffer_size());
    let channels = match frame.color_type {
        png::ColorType::Grayscale => 1,
        png::ColorType::GrayscaleAlpha => 2,
        png::ColorType::Rgb => 3,
        png::ColorType::Rgba => 4,
        png::ColorType::Indexed => return Err("an indexed-colour PNG that could not be expanded".to_string()),
    };
    let rgba: Vec<u8> = buffer
        .chunks_exact(channels)
        .flat_map(|p| match channels {
            1 => [p[0], p[0], p[0], 255],
            2 => [p[0], p[0], p[0], p[1]],
            3 => [p[0], p[1], p[2], 255],
            _ => [p[0], p[1], p[2], p[3]],
        })
        .collect();
    Ok((frame.width, frame.height, rgba))
}

/// One of the project's files the workspace lists.
#[derive(Debug, Clone)]
pub(crate) struct Own {
    /// Its archive path, as the project folder spells it.
    pub(crate) vpath: String,
    pub(crate) kind: Kind,
    pub(crate) bytes: u64,
}

/// What the workspace asked for, carried out by [`answer`] after the panel
/// is drawn.
#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) enum Ask {
    /// Choose a picture with the system's file dialog, then open the import
    /// dialog on it, in `folder`, named `name` (or after the picture), for
    /// `for_field` when a form asked. With `any`, the file dialog also offers
    /// glTF models and WAV and MP3 files: a model opens the Import Model
    /// dialog, and one or more sounds open the Import Sound dialog.
    Choose {
        folder: String,
        name: Option<String>,
        for_field: Option<FieldTarget>,
        any: bool,
    },
    /// Choose WAV or MP3 files with the system's file dialog, then open the
    /// Import Sound dialog on them. `for_field` is the `SoundEntries` field
    /// whose picker asked, if any. See [`super::sounds`].
    ChooseSounds { for_field: Option<FieldTarget> },
    /// Write the open import.
    Import,
    /// Write the open model import. See [`super::models`].
    ImportModel,
    /// Write the open sound import.
    ImportSound,
    /// Add a `SoundEntries` row whose `Directory` and `File 1` hold the
    /// project sound file at this archive path, which no row holds yet.
    AddEntry(String),
    /// Open the import dialog again on the file one of the project's files
    /// was imported from, with the choices it was imported with.
    Reimport(String),
    /// Open the import dialog on one of the project's own BLP files, to write
    /// it again: at its own path for what its folder says it is for, or for
    /// `purpose` (a texture imported elsewhere made a ground texture). A
    /// ground texture without its `_s` file is written as the pair this way.
    Rewrite { vpath: String, purpose: Option<Purpose> },
    /// Remove one of the project's files.
    Remove(String),
    /// Choose a file with the system's file dialog and import it at the
    /// archive path `vpath`, in its folder and under its name, so the
    /// project's file is read in place of the archives': a picture for a BLP
    /// texture, a glTF model for an M2, one WAV or MP3 for a sound. See
    /// [`super::files`].
    Replace(String),
}

/// The workspace's state.
#[derive(Resource, Default)]
pub(crate) struct Assets {
    /// The selected file's archive path.
    pub(crate) selected: Option<String>,
    /// What the search box holds.
    pub(crate) query: String,
    /// The open import dialog.
    pub(crate) import: Option<Import>,
    /// The open Import Model dialog.
    pub(crate) model: Option<super::models::ModelImport>,
    /// The open Import Sound dialog.
    pub(crate) sound: Option<super::sounds::SoundImport>,
    /// What the generated files were made from. See [`super::generated`].
    pub(crate) surveys: super::generated::Surveys,
    pub(crate) ask: Option<Ask>,
    /// A texture imported for a form field, and its name, for the form to
    /// write into the field. Taken by the form.
    pub(crate) imported_for: Option<(FieldTarget, String)>,
    /// The texture an import last wrote and what it is for, for the shell:
    /// a ground texture goes on the texture tool's brush. Taken by the shell.
    pub(crate) imported: Option<(String, Purpose)>,
    /// The folder the last picture was chosen from, where the file dialog
    /// opens next.
    pub(crate) picture_dir: Option<PathBuf>,
    /// The project's asset files and the `EditSession::files_revision` they
    /// were listed at.
    listed: Option<(u64, Vec<Own>)>,
    /// The import record, read at the same revision.
    sources: Option<(u64, super::sources::Sources)>,
}

impl Assets {
    /// The project's asset files: every file the publish packs, in path order,
    /// listed again when the project's files change.
    pub(crate) fn files(&mut self, session: &EditSession) -> &[Own] {
        let current = self
            .listed
            .as_ref()
            .is_some_and(|(at, _)| *at == session.files_revision);
        if !current {
            let found = session
                .project
                .files()
                .into_iter()
                .filter(|vpath| Project::is_game_data(vpath))
                .map(|vpath| (Kind::of(&vpath), vpath))
                .map(|(kind, vpath)| Own {
                    bytes: session
                        .project
                        .path_for(&vpath)
                        .and_then(|path| std::fs::metadata(path).ok())
                        .map_or(0, |meta| meta.len()),
                    vpath,
                    kind,
                })
                .collect();
            self.listed = Some((session.files_revision, found));
        }
        self.listed.as_ref().map_or(&[], |(_, found)| found)
    }

    /// Whether an import dialog is open. An open dialog takes the clicks of
    /// the whole window it is drawn in.
    pub(crate) fn dialog_open(&self) -> bool {
        self.import.is_some() || self.model.is_some() || self.sound.is_some()
    }

    /// Whether a table field opened the open dialog. That decides which
    /// window the dialog is drawn in; see `crate::popout::Popout::import_window`.
    pub(crate) fn asked_by_field(&self) -> bool {
        self.import.as_ref().is_some_and(|import| import.for_field.is_some())
            || self.sound.as_ref().is_some_and(|sound| sound.for_field.is_some())
    }

    /// The import record, read again when the project's files change.
    pub(crate) fn sources(&mut self, session: &EditSession) -> &super::sources::Sources {
        let current = self.sources.as_ref().is_some_and(|(at, _)| *at == session.files_revision);
        if !current {
            self.sources = Some((session.files_revision, super::sources::Sources::read(&session.project)));
        }
        &self.sources.as_ref().expect("read above").1
    }
}

pub(crate) struct AssetsPlugin;

impl Plugin for AssetsPlugin {
    fn build(&self, app: &mut App) {
        app.init_resource::<Assets>()
            .init_resource::<super::files::GameFiles>()
            .init_resource::<crate::jobs::Running<super::files::Exported>>()
            .add_systems(Update, (on_the_command_line, answer, super::files::answer).chain());
    }
}

/// `--import-texture <picture> <archive path>`: open the import on the
/// picture with the path's folder and name, and write it, once there is a
/// session. `--import-model` and `--import-sound` do the same for a model
/// and a sound, and `--import-dialog` opens a dialog without writing. See
/// `crate::args::import::Import`.
fn on_the_command_line(
    args: Res<crate::args::Args>,
    mut assets: ResMut<Assets>,
    session: Option<ResMut<EditSession>>,
    game: Res<vale_client::assets::GameAssets>,
    mut done: Local<bool>,
) {
    let Some(mut session) = session.filter(|_| !*done) else { return };
    *done = true;
    let tables = game.display_tables().ok();
    let animations = tables.as_deref().and_then(|t| t.animations());
    if let Some((file, vpath)) = args.import.import_sound.clone() {
        let vpath = vpath.replace('/', "\\");
        let (folder, written) = vpath.rsplit_once('\\').unwrap_or(("", vpath.as_str()));
        let name = written.rsplit_once('.').map_or(written, |(stem, _)| stem).to_string();
        match super::sounds::SoundImport::open(&[PathBuf::from(&file)], &format!("{folder}\\"), None) {
            Ok(mut import) => {
                info!("--import-sound: {file}: {}, {:.2} s", import.files[0].format.map_or_else(|| "unknown".to_string(), |f| f.words()), import.files[0].pcm.seconds());
                import.files[0].name = name.clone();
                import.entry.name = name;
                assets.sound = Some(import);
                assets.ask = Some(Ask::ImportSound);
            }
            Err(why) => warn!("--import-sound: {why}"),
        }
        return;
    }
    if let Some((model, vpath)) = args.import.import_model.clone() {
        let vpath = vpath.replace('/', "\\");
        let (folder, name) = match vpath.rfind('\\') {
            Some(at) => (vpath[..=at].to_string(), Some(vpath[at + 1..].trim_end_matches(".m2").to_string())),
            None => (super::models::OTHER_FOLDER.to_string(), None),
        };
        match super::models::ModelImport::open(Path::new(&model), &folder, name, animations, None) {
            Ok(import) => {
                info!(
                    "--import-model: {model}: {} vertices, {} bones, {} clips",
                    import.source.vertices,
                    import.source.bones.len(),
                    import.source.clips.len()
                );
                assets.model = Some(import);
                assets.ask = Some(Ask::ImportModel);
            }
            Err(why) => warn!("--import-model: {why}"),
        }
        return;
    }
    if let Some((picture, purpose)) = args.import.import_dialog.clone() {
        // A WAV or MP3 opens the Import Sound dialog, for the purpose the
        // second argument names. `SoundEntries` is opened first, because the
        // dialog shows which rows already hold the file's path.
        if super::sounds::is_sound_file(Path::new(&picture)) {
            session.open_table(&game, super::sounds::TABLE);
            let folder = super::sounds::SoundPurpose::of_word(&purpose).map_or(String::new(), |p| p.root().to_string());
            match super::sounds::SoundImport::open(&[PathBuf::from(&picture)], &folder, None) {
                Ok(import) => assets.sound = Some(import),
                Err(why) => warn!("--import-dialog: {why}"),
            }
            return;
        }
        // A model file opens the Import Model dialog, for `creature`,
        // `doodad` or `other` (the default).
        if super::models::is_model_file(Path::new(&picture)) {
            let folder = match purpose.to_ascii_lowercase().as_str() {
                "creature" => super::models::CREATURE_ROOT,
                "doodad" => super::models::DOODAD_FOLDER,
                _ => super::models::OTHER_FOLDER,
            };
            match super::models::ModelImport::open(Path::new(&picture), folder, None, animations, None) {
                Ok(import) => assets.model = Some(import),
                Err(why) => warn!("--import-dialog: {why}"),
            }
            return;
        }
        let purpose = match purpose.to_ascii_lowercase().as_str() {
            "ground" => Purpose::Ground,
            "icon" => Purpose::Icon,
            _ => Purpose::Other,
        };
        match read_picture(Path::new(&picture)) {
            Ok(read) => {
                let name = Path::new(&picture)
                    .file_stem()
                    .and_then(|stem| stem.to_str())
                    .unwrap_or("Texture")
                    .to_string();
                let mut import = Import::new(PathBuf::from(&picture), read, OTHER_FOLDER.to_string(), name, None);
                import.set_purpose(purpose);
                assets.import = Some(import);
            }
            Err(why) => warn!("--import-dialog: {why}"),
        }
    }
    let Some((picture, vpath)) = args.import.import_texture.clone() else { return };
    let vpath = vpath.replace('/', "\\");
    let (folder, file) = match vpath.rfind('\\') {
        Some(at) => (vpath[..=at].to_string(), vpath[at + 1..].to_string()),
        None => (String::new(), vpath.clone()),
    };
    let name = file
        .strip_suffix(".blp")
        .or_else(|| file.strip_suffix(".BLP"))
        .unwrap_or(&file)
        .to_string();
    match read_picture(Path::new(&picture)) {
        Ok((width, height, rgba)) => {
            info!("--import-texture: {picture} is {width}x{height}");
            assets.import = Some(Import::new(
                PathBuf::from(&picture),
                (width, height, rgba),
                folder,
                name,
                None,
            ));
            assets.ask = Some(Ask::Import);
        }
        Err(why) => warn!("--import-texture: {why}"),
    }
}

/// Carry out what the panel asked for: the file dialog, the write, the
/// removal.
fn answer(
    mut assets: ResMut<Assets>,
    mut session: Option<ResMut<EditSession>>,
    mut thumbnails: ResMut<crate::ui::widgets::thumbnails::Thumbnails>,
    game: Res<vale_client::assets::GameAssets>,
    // Its text buffers are cleared after a sound import adds a row or sets a
    // field, so the open form reads the table again instead of the text it
    // showed before.
    mut browser: Option<ResMut<crate::tables::browser::Browser>>,
) {
    let Some(ask) = assets.ask.take() else { return };
    let Some(session) = session.as_mut() else { return };
    let tables = game.display_tables().ok();
    let animations = tables.as_deref().and_then(|t| t.animations());
    match ask {
        Ask::Choose { folder, name: chosen, for_field, any } => {
            let mut dialog = match any {
                true => rfd::FileDialog::new()
                    .add_filter("Picture, model or sound", &["png", "tga", "blp", "glb", "gltf", "wav", "mp3"])
                    .add_filter("Picture", &["png", "tga", "blp"])
                    .add_filter("Model (glTF 2.0)", &["glb", "gltf"])
                    .add_filter("Sound", &["wav", "mp3"]),
                false => rfd::FileDialog::new().add_filter("Picture", &["png", "tga", "blp"]),
            };
            if let Some(dir) = &assets.picture_dir {
                dialog = dialog.set_directory(dir);
            }
            // Several WAV or MP3 files can become the files of one
            // `SoundEntries` row, so this file dialog allows several files.
            let picked = match any {
                true => dialog.pick_files().unwrap_or_default(),
                false => dialog.pick_file().into_iter().collect(),
            };
            let Some(path) = picked.first().cloned() else { return };
            assets.picture_dir = path.parent().map(Path::to_path_buf);
            if any && picked.iter().all(|p| super::sounds::is_sound_file(p)) {
                // `SoundEntries` is opened first, because the dialog shows
                // which rows already hold the file's path.
                session.open_table(&game, super::sounds::TABLE);
                match super::sounds::SoundImport::open(&picked, "", None) {
                    Ok(import) => assets.sound = Some(import),
                    Err(why) => session.status = why,
                }
                return;
            }
            if picked.len() > 1 {
                session.status = "Choose one picture or one model, or any number of sounds.".to_string();
                return;
            }
            if any && super::models::is_model_file(&path) {
                // The texture import's starting folder says nothing about a
                // model: with no folder, the model import chooses creature or
                // doodad by whether the model has animations.
                let folder = match folder == OTHER_FOLDER {
                    true => String::new(),
                    false => folder,
                };
                match super::models::ModelImport::open(&path, &folder, chosen, animations, None) {
                    Ok(import) => assets.model = Some(import),
                    Err(why) => session.status = why,
                }
                return;
            }
            match read_picture(&path) {
                Ok((width, height, rgba)) => {
                    let name = chosen.unwrap_or_else(|| {
                        path.file_stem()
                            .and_then(|stem| stem.to_str())
                            .unwrap_or("Texture")
                            .to_string()
                    });
                    let name = match &for_field {
                        Some(target) => target.file_name(&name),
                        None => name,
                    };
                    // The shell draws the dialog under any tool, so the tool
                    // that asked (the workspace, a form, the texture tool) stays.
                    assets.import = Some(Import::new(path, (width, height, rgba), folder, name, for_field));
                }
                Err(why) => session.status = why,
            }
        }
        Ask::ChooseSounds { for_field } => {
            let mut dialog = rfd::FileDialog::new().add_filter("Sound", &["wav", "mp3"]);
            if let Some(dir) = &assets.picture_dir {
                dialog = dialog.set_directory(dir);
            }
            let Some(picked) = dialog.pick_files().filter(|p| !p.is_empty()) else { return };
            assets.picture_dir = picked[0].parent().map(Path::to_path_buf);
            // The field's table sets the purpose, and the new row copies its
            // values and `Directory` from a `SoundEntries` row the field's
            // record names (`sounds::suggested`).
            let purpose = for_field.as_ref().map(|t| super::sounds::SoundPurpose::for_table(&t.table));
            let suggested = for_field.as_ref().and_then(|t| {
                session.open_table(&game, super::sounds::TABLE);
                super::sounds::suggested(session, t)
            });
            let folder = purpose.map_or(String::new(), |p| p.root().to_string());
            match super::sounds::SoundImport::open(&picked, &folder, None) {
                Ok(mut import) => {
                    if let Some((values, directory)) = suggested {
                        import.take_from(values, &directory);
                    }
                    import.for_field = for_field;
                    assets.sound = Some(import);
                }
                Err(why) => session.status = why,
            }
        }
        Ask::ImportSound => {
            let Some(import) = assets.sound.take() else { return };
            if let Some(problem) = import.problems().into_iter().next() {
                session.status = problem;
                assets.sound = Some(import);
                return;
            }
            // The rows that already hold the first file's path: a re-import,
            // or a file written over one of the archives' files.
            // `SoundImport::reuses` decides from them whether a row is added.
            let first = import.vpath(0);
            session.open_table(&game, super::sounds::TABLE);
            let named = session.table(super::sounds::TABLE).map(|t| super::sounds::rows_naming(t, &first)).unwrap_or_default();
            let reused = import.reuses(&named);
            let mut saved = true;
            for (path, bytes) in import.encode() {
                saved &= session.save_bytes(&path, bytes);
            }
            if !saved {
                assets.sound = Some(import);
                return;
            }
            let settings = import.settings();
            for (file, written) in import.files.iter().zip((0..import.files.len()).map(|f| import.vpath(f))) {
                let entry = super::sources::Imported { vpath: written, source: file.source.clone(), settings: settings.clone() };
                if let Err(why) = super::sources::Sources::record(&session.project, entry) {
                    warn!("the import record was not written: {why}");
                }
            }
            let written = match import.files.len() {
                1 => first.clone(),
                n => format!("{n} sounds into {}", import.directory()),
            };
            let ids: Vec<String> = named.iter().map(u32::to_string).collect();
            let mut added = None;
            session.status = match (reused, import.row) {
                (true, _) => format!("imported {written}, played by SoundEntries {}", ids.join(", ")),
                (false, false) => format!("imported {written}; no SoundEntries row holds it, so the game does not play it"),
                (false, true) => {
                    let files: Vec<String> = (0..import.files.len())
                        .map(|f| import.vpath(f).rsplit('\\').next().unwrap_or_default().to_string())
                        .collect();
                    let target = import.for_field.as_ref().filter(|t| session.table(&t.table).is_some());
                    added = super::sounds::add_entry(session, &import.entry, &import.directory(), &files, target);
                    match added {
                        Some(id) => format!("imported {written}, with SoundEntries {id} \"{}\"", import.entry.name.trim()),
                        None => format!("imported {written}; the SoundEntries row could not be added"),
                    }
                }
            };
            if let Some(browser) = browser.as_mut() {
                browser.forget_buffers();
                // An import no field opened, started while the browser shows
                // `SoundEntries`, opens the new row.
                if let (Some(id), None, true) = (added, &import.for_field, browser.table == super::sounds::TABLE) {
                    browser.index(&session, super::sounds::TABLE);
                    browser.follow(&session, super::sounds::TABLE, id);
                }
            }
            assets.selected = Some(first);
        }
        Ask::AddEntry(vpath) => {
            session.open_table(&game, super::sounds::TABLE);
            let (directory, file) = vpath.rsplit_once('\\').unwrap_or(("", vpath.as_str()));
            let name = file.rsplit_once('.').map_or(file, |(stem, _)| stem);
            let values = super::sounds::SoundPurpose::of_path(&vpath).values(name);
            session.status = match super::sounds::add_entry(session, &values, directory, &[file.to_string()], None) {
                Some(id) => format!("added SoundEntries {id} \"{name}\", which plays {vpath}"),
                None => format!("the SoundEntries row for {vpath} could not be added"),
            };
            if let Some(browser) = browser.as_mut() {
                browser.forget_buffers();
            }
        }
        Ask::Import => {
            let Some(import) = assets.import.take() else { return };
            if let Some(problem) = import.problems().into_iter().next() {
                session.status = problem;
                assets.import = Some(import);
                return;
            }
            let files = match import.encode() {
                Ok(files) => files,
                Err(why) => {
                    session.status = why;
                    assets.import = Some(import);
                    return;
                }
            };
            let vpath = import.vpath();
            let mut saved = true;
            for (path, bytes) in files {
                // A picture already drawn at this path is the file it replaces.
                thumbnails.forget(&path);
                saved &= session.save_bytes(&path, bytes);
            }
            if saved {
                let (width, height) = import.written_size();
                let mips = match import.mips {
                    true => ", with mips",
                    false => "",
                };
                session.status = match import.gloss_vpath() {
                    Some(gloss) => format!(
                        "imported {vpath} (DXT1) and {gloss} (DXT3, its gloss): {width}x{height}{mips}"
                    ),
                    None => format!("imported {vpath}: {width}x{height}, {}{mips}", import.encoding().name()),
                };
                // Only a picture from disk has a source to import again; a
                // project texture written again does not.
                if import.source.is_file() {
                    let entry = super::sources::Imported {
                        vpath: vpath.clone(),
                        source: import.source.clone(),
                        settings: vec![("purpose".to_string(), format!("{:?}", import.purpose).to_ascii_lowercase())],
                    };
                    if let Err(why) = super::sources::Sources::record(&session.project, entry) {
                        session.status = format!("{}; the import record was not written: {why}", session.status);
                    }
                }
                assets.selected = Some(vpath.clone());
                assets.imported = Some((vpath, import.purpose));
                if let Some(target) = import.for_field {
                    let text = target.field_text(import.name.trim());
                    assets.imported_for = Some((target, text));
                }
            }
        }
        Ask::ImportModel => {
            let Some(import) = assets.model.take() else { return };
            if let Some(problem) = import.problems().into_iter().next() {
                session.status = problem;
                assets.model = Some(import);
                return;
            }
            let files = match import.encode(animations) {
                Ok(files) => files,
                Err(why) => {
                    session.status = why;
                    assets.model = Some(import);
                    return;
                }
            };
            let vpath = import.vpath();
            let mut saved = true;
            let mut textures = 0usize;
            for (path, bytes) in files {
                thumbnails.forget(&path);
                saved &= session.save_bytes(&path, bytes);
                textures += usize::from(path != vpath);
            }
            if saved {
                let settings = import.settings();
                for path in std::iter::once(vpath.clone()).chain((0..import.textures.len()).filter_map(|s| import.texture_vpath(s))) {
                    let entry = super::sources::Imported { vpath: path, source: import.source_path.clone(), settings: settings.clone() };
                    if let Err(why) = super::sources::Sources::record(&session.project, entry) {
                        warn!("the import record was not written: {why}");
                    }
                }
                let taken = import.clips.iter().filter(|c| c.take).count();
                session.status = format!(
                    "imported {vpath}: {} vertices, {} bones, {taken} sequences, {textures} textures",
                    import.source.vertices,
                    import.source.bones.len()
                );
                assets.selected = Some(vpath);
                assets.surveys.forget();
            }
        }
        Ask::Reimport(vpath) => {
            let Some(entry) = assets.sources(session).of(&vpath).cloned() else {
                session.status = format!("{vpath} has no import record, so its source is not known");
                return;
            };
            if super::sounds::is_sound_file(&entry.source) {
                session.open_table(&game, super::sounds::TABLE);
                match super::sounds::SoundImport::open(std::slice::from_ref(&entry.source), &entry.vpath, Some(&entry)) {
                    Ok(import) => assets.sound = Some(import),
                    Err(why) => session.status = why,
                }
                return;
            }
            if super::models::is_model_file(&entry.source) {
                // The model's own line, which a texture written for it shares.
                let model = assets
                    .sources(session)
                    .entries
                    .iter()
                    .find(|e| e.source == entry.source && e.vpath.to_ascii_lowercase().ends_with(".m2"))
                    .cloned()
                    .unwrap_or(entry);
                match super::models::ModelImport::open(&model.source, &model.vpath, None, animations, Some(&model)) {
                    Ok(import) => assets.model = Some(import),
                    Err(why) => session.status = why,
                }
                return;
            }
            match read_picture(&entry.source) {
                Ok(read) => {
                    let (folder, file) = match vpath.rfind('\\') {
                        Some(at) => (vpath[..=at].to_string(), &vpath[at + 1..]),
                        None => (String::new(), vpath.as_str()),
                    };
                    let name = file.get(..file.len().saturating_sub(4)).unwrap_or(file).to_string();
                    assets.import = Some(Import::new(entry.source.clone(), read, folder, name, None));
                }
                Err(why) => session.status = why,
            }
        }
        Ask::Rewrite { vpath, purpose } => {
            let decoded = session
                .project
                .read(&vpath)
                .ok_or_else(|| format!("{vpath} is not one of the project's files"))
                .and_then(|bytes| blp::decode(&bytes).map_err(|e| format!("{vpath}: {e}")));
            match decoded {
                Ok(picture) => {
                    let (folder, file) = match vpath.rfind('\\') {
                        Some(at) => (vpath[..=at].to_string(), &vpath[at + 1..]),
                        None => (String::new(), vpath.as_str()),
                    };
                    let name = file.get(..file.len().saturating_sub(4)).unwrap_or(file).to_string();
                    let mut import = Import::new(
                        PathBuf::from(&vpath),
                        (picture.width, picture.height, picture.rgba),
                        folder,
                        name,
                        None,
                    );
                    if let Some(purpose) = purpose {
                        import.set_purpose(purpose);
                    }
                    assets.import = Some(import);
                }
                Err(why) => session.status = why,
            }
        }
        Ask::Replace(vpath) => {
            let (folder, file) = match vpath.rsplit_once('\\') {
                Some((folder, file)) => (format!("{folder}\\"), file),
                None => (String::new(), vpath.as_str()),
            };
            let stem = file.rsplit_once('.').map_or(file, |(stem, _)| stem).to_string();
            match Kind::of(&vpath) {
                // The texture dialog's own route, which this answer takes on
                // the next frame.
                Kind::Texture | Kind::Minimap => {
                    assets.ask = Some(Ask::Choose { folder, name: Some(stem), for_field: None, any: false });
                }
                Kind::Model => {
                    let mut dialog = rfd::FileDialog::new().add_filter("Model (glTF 2.0)", &["glb", "gltf"]);
                    if let Some(dir) = &assets.picture_dir {
                        dialog = dialog.set_directory(dir);
                    }
                    let Some(path) = dialog.pick_file() else { return };
                    assets.picture_dir = path.parent().map(Path::to_path_buf);
                    match super::models::ModelImport::open(&path, &folder, Some(stem), animations, None) {
                        Ok(import) => assets.model = Some(import),
                        Err(why) => session.status = why,
                    }
                }
                Kind::Sound => {
                    let mut dialog = rfd::FileDialog::new().add_filter("Sound", &["wav", "mp3"]);
                    if let Some(dir) = &assets.picture_dir {
                        dialog = dialog.set_directory(dir);
                    }
                    let Some(path) = dialog.pick_file() else { return };
                    assets.picture_dir = path.parent().map(Path::to_path_buf);
                    // `SoundEntries` is opened first, because the dialog
                    // shows which rows already hold the file's path.
                    session.open_table(&game, super::sounds::TABLE);
                    match super::sounds::SoundImport::open(&[path], &folder, None) {
                        Ok(mut import) => {
                            import.files[0].name = stem;
                            assets.sound = Some(import);
                        }
                        Err(why) => session.status = why,
                    }
                }
                _ => session.status = format!("{vpath} is not a texture, a model or a sound, which are the files an import writes"),
            }
        }
        Ask::Remove(vpath) => {
            // A ground texture is removed with its `_s` file. The client
            // reads one or the other depending on its `specular` setting, so
            // with either file left alone the ground is drawn as a missing
            // texture under one of the two settings.
            let mut gone = vec![vpath.clone()];
            if let Some(gloss) = gloss_of(&vpath) {
                if session.project.has(&gloss) {
                    gone.push(gloss);
                }
            }
            for path in gone {
                thumbnails.forget(&path);
                session.remove_file(&path);
                super::sources::Sources::forget(&session.project, &path);
            }
            assets.surveys.forget();
            if assets.selected.as_deref() == Some(vpath.as_str()) {
                assets.selected = None;
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    /// A body texture is written with `_U` and its field names it without.
    /// A name that already ends in a body's suffix is kept as it is.
    #[test]
    fn a_body_texture_is_written_with_its_suffix_and_named_without() {
        let target = FieldTarget {
            table: "ItemDisplayInfo".to_string(),
            record: 0,
            field: 17,
            suffix: "_U",
        };
        assert_eq!(target.file_name("Robe_Chest_TU"), "Robe_Chest_TU_U");
        assert_eq!(target.file_name("Robe_Chest_TU_F"), "Robe_Chest_TU_F");
        assert_eq!(target.field_text("Robe_Chest_TU_U"), "Robe_Chest_TU");
        let skin = FieldTarget { suffix: "", ..target };
        assert_eq!(skin.file_name("WolfSkinBlue_u"), "WolfSkinBlue_u");
        assert_eq!(skin.field_text("WolfSkinBlue_u"), "WolfSkinBlue_u");
    }

    fn import(width: u32, height: u32) -> Import {
        Import {
            resize: false,
            ..Import::new(
                PathBuf::from("grass.png"),
                (width, height, vec![255; (width * height * 4) as usize]),
                "Textures/Custom".to_string(),
                "Grass".to_string(),
                None,
            )
        }
    }

    /// A ground texture is the plain file in DXT1 and its `_s` file in DXT3
    /// with the gloss in its alpha, scaled down to the largest shipped size.
    #[test]
    fn a_ground_texture_is_written_with_its_gloss_file() {
        let mut rgba = vec![200u8; 512 * 512 * 4];
        for pixel in rgba.chunks_exact_mut(4) {
            pixel[3] = 96;
        }
        let ground = Import::new(
            PathBuf::from("rock.png"),
            (512, 512, rgba),
            "Tileset\\Custom".to_string(),
            "Rock".to_string(),
            None,
        );
        assert!(ground.ground());
        assert_eq!(ground.purpose, Purpose::Ground);
        assert_eq!(ground.gloss, Gloss::FromAlpha);
        assert_eq!(ground.written_size(), (GROUND_SIDE, GROUND_SIDE));
        let files = ground.encode().expect("encoded");
        assert_eq!(files[0].0, "Tileset\\Custom\\Rock.blp");
        assert_eq!(files[1].0, "Tileset\\Custom\\Rock_s.blp");
        let plain = blp::decode(&files[0].1).expect("plain");
        let gloss = blp::decode(&files[1].1).expect("gloss");
        assert_eq!((plain.width, plain.height), (256, 256));
        assert_eq!(files[0].1[8..10], [2, 0], "DXT1, no alpha");
        assert_eq!(files[1].1[8..11], [2, 8, 1], "DXT3");
        assert!(plain.rgba.chunks_exact(4).all(|pixel| pixel[3] == 255));
        assert!(gloss.rgba.chunks_exact(4).all(|pixel| pixel[3].abs_diff(96) <= 9));
        let mut matte = ground.clone();
        matte.gloss = Gloss::Matte;
        let gloss = blp::decode(&matte.encode().expect("encoded")[1].1).expect("gloss");
        assert!(gloss.rgba.chunks_exact(4).all(|pixel| pixel[3] == 0));
        let mut named = ground;
        named.name = "Rock_s".to_string();
        assert!(!named.problems().is_empty());
    }

    /// A typed folder becomes one archive folder, and the file is named in it.
    #[test]
    fn the_path_is_the_folder_and_the_name() {
        assert_eq!(import(64, 64).vpath(), "Textures\\Custom\\Grass.blp");
        assert_eq!(folder_of("\\Creature\\Wolf\\"), "Creature\\Wolf\\");
        assert_eq!(folder_of("  "), "");
    }

    /// Choosing what a texture is for moves it: a ground texture under
    /// `Tileset\`, an icon to `Interface\Icons\` at 64x64, and Other out of
    /// both. The pair is removed together.
    #[test]
    fn the_purpose_decides_the_folder_and_the_size() {
        let mut texture = import(512, 512);
        assert_eq!(texture.purpose, Purpose::Other);
        texture.set_purpose(Purpose::Ground);
        assert_eq!(texture.vpath(), "Tileset\\Custom\\Grass.blp");
        assert_eq!(texture.written_size(), (256, 256));
        texture.folder = "Tileset\\Moor\\".to_string();
        texture.set_purpose(Purpose::Ground);
        assert_eq!(texture.vpath(), "Tileset\\Moor\\Grass.blp", "a ground folder is kept");
        texture.set_purpose(Purpose::Icon);
        assert_eq!(texture.vpath(), "Interface\\Icons\\Grass.blp");
        assert_eq!(texture.written_size(), (64, 64));
        assert_eq!(texture.gloss_vpath(), None);
        texture.set_purpose(Purpose::Other);
        assert_eq!(texture.vpath(), "Textures\\Custom\\Grass.blp");
        assert_eq!(texture.written_size(), (512, 512));
        assert_eq!(
            gloss_of("Tileset\\Custom\\Grass.blp").as_deref(),
            Some("Tileset\\Custom\\Grass_s.blp")
        );
        assert_eq!(gloss_of("Tileset\\Custom\\Grass_s.blp"), None);
        assert_eq!(gloss_of("Textures\\Custom\\Grass.blp"), None);
    }

    /// A side that is not a power of two is refused until the dialog resizes
    /// it, and the resize is up to the next power of two.
    #[test]
    fn a_picture_that_is_not_powers_of_two_needs_the_resize() {
        let mut odd = import(100, 64);
        assert!(!odd.problems().is_empty());
        odd.resize = true;
        assert!(odd.problems().is_empty(), "{:?}", odd.problems());
        assert_eq!(odd.written_size(), (128, 64));
        let files = odd.encode().expect("encoded");
        assert_eq!(files.len(), 1, "not a ground texture: one file");
        let back = blp::decode(&files[0].1).expect("decoded");
        assert_eq!((back.width, back.height), (128, 64));
    }

    /// An opaque picture is DXT1, and a name or folder that would put the file
    /// where nothing finds it is refused.
    #[test]
    fn the_encoding_and_the_refusals() {
        let mut ok = import(32, 32);
        assert_eq!(ok.encoding(), Encoding::Dxt1);
        ok.name = "a/b".to_string();
        assert!(!ok.problems().is_empty());
        let mut root = import(32, 32);
        root.folder.clear();
        assert!(!root.problems().is_empty());
        let mut private = import(32, 32);
        private.folder = "sql\\".to_string();
        assert!(!private.problems().is_empty());
    }
}
